INSERT INTO kpi_lineage(lineage_root,started_at,first_served_at) SELECT c.lineage_root,MIN(c.lineage_started_at),MIN((SELECT MIN(created_at) FROM (
  SELECT MIN(r.created_at) AS created_at FROM spore_injections r WHERE r.project_id=sess.project_id AND r.session_id=sess.session_id
  UNION ALL SELECT MIN(r.created_at) FROM session_injections r WHERE r.project_id=sess.project_id AND r.session_id=sess.session_id))) FROM (SELECT c.lineage_root FROM sessions s JOIN member_credentials c ON c.id=s.created_by_token_id WHERE s.project_id=OLD.project_id AND s.session_id=OLD.session_id AND OLD.created_at <= (SELECT first_served_at FROM kpi_lineage WHERE lineage_root=c.lineage_root)) roots JOIN member_credentials c INDEXED BY idx_member_credentials_lineage ON c.lineage_root=roots.lineage_root
    JOIN sessions sess INDEXED BY idx_sessions_credential ON sess.created_by_token_id=c.id WHERE true GROUP BY c.lineage_root
