      WHERE (kpi_fact.day,kpi_fact.harness,kpi_fact.prompts,kpi_fact.served,kpi_fact.with_spores,kpi_fact.claimed,kpi_fact.unrecognized,kpi_fact.unmarked,kpi_fact.opener_conflict,kpi_fact.contract_violation,kpi_fact.reused,kpi_fact.calls,kpi_fact.plan_reads,kpi_fact.sessions,kpi_fact.started_with_block,kpi_fact.deliveries,kpi_fact.placed,kpi_fact.identity_conflicts,kpi_fact.duplicate_skips,kpi_fact.scheme_conflicts,kpi_fact.mixed_sessions) IS NOT (excluded.day,excluded.harness,excluded.prompts,excluded.served,excluded.with_spores,excluded.claimed,excluded.unrecognized,excluded.unmarked,excluded.opener_conflict,excluded.contract_violation,excluded.reused,excluded.calls,excluded.plan_reads,excluded.sessions,excluded.started_with_block,excluded.deliveries,excluded.placed,excluded.identity_conflicts,excluded.duplicate_skips,excluded.scheme_conflicts,excluded.mixed_sessions);
DELETE FROM kpi_fact WHERE grain='p' AND (project_id,session_id,key) IN (SELECT project_id,session_id,k FROM (SELECT NEW.project_id AS project_id,NEW.session_id AS session_id,NEW.delivered_prompt_id AS k))
      AND NOT EXISTS (SELECT 1 FROM (SELECT q.project_id,q.session_id,q.k AS key,CAST((x.created_at - ((x.created_at % 86400000 + 86400000) % 86400000)) / 86400000 AS INTEGER) AS day,COALESCE((SELECT tr.agent FROM transcripts tr INDEXED BY idx_transcripts_session WHERE tr.project_id=x.project_id AND tr.session_id=x.session_id AND tr.role='primary' ORDER BY tr.first_received_at,tr.transcript_id LIMIT 1),'unrecorded') AS harness,
    1 AS prompts,(EXISTS (SELECT 1 FROM spore_injections r WHERE r.project_id=x.project_id AND r.session_id=x.session_id AND r.delivered_prompt_id=x.prompt_id AND r.delivered_at IS NOT NULL) OR EXISTS (SELECT 1 FROM session_injections r WHERE r.project_id=x.project_id AND r.session_id=x.session_id AND r.kind='plan-nudge' AND r.delivered_prompt_id=x.prompt_id AND r.delivered_at IS NOT NULL)) AS served,EXISTS (SELECT 1 FROM spore_injections r WHERE r.project_id=x.project_id AND r.session_id=x.session_id AND r.delivered_prompt_id=x.prompt_id AND r.delivered_at IS NOT NULL AND r.spore_ids<>'[]') AS with_spores,x.claim IS NOT NULL AS claimed,(x.claim IS NOT NULL AND x.prompt_kind='unrecognized') AS unrecognized,(x.claim IS NOT NULL AND x.prompt_kind='unmarked') AS unmarked,(x.claim IS NOT NULL AND x.prompt_kind='opener_conflict') AS opener_conflict,(x.claim IS NOT NULL AND x.prompt_kind='contract_violation') AS contract_violation,COALESCE(x.claim='reused',0) AS reused,0 AS calls,0 AS plan_reads,0 AS sessions,0 AS started_with_block,0 AS deliveries,0 AS placed,0 AS identity_conflicts,0 AS duplicate_skips,0 AS scheme_conflicts,0 AS mixed_sessions FROM (SELECT NEW.project_id AS project_id,NEW.session_id AS session_id,NEW.delivered_prompt_id AS k) q JOIN session_prompts x ON x.project_id=q.project_id AND x.session_id=q.session_id AND x.prompt_id=q.k WHERE x.generation=(SELECT doc.generation FROM session_documents doc WHERE doc.project_id=q.project_id AND doc.session_id=q.session_id AND doc.state='live')) e WHERE e.project_id=kpi_fact.project_id AND e.session_id=kpi_fact.session_id AND e.key=kpi_fact.key);
INSERT INTO kpi_fact(project_id,session_id,grain,key,day,harness,prompts,served,with_spores,claimed,unrecognized,unmarked,opener_conflict,contract_violation,reused,calls,plan_reads,sessions,started_with_block,deliveries,placed,identity_conflicts,duplicate_skips,scheme_conflicts,mixed_sessions)
      SELECT project_id,session_id,'p',key,day,harness,prompts,served,with_spores,claimed,unrecognized,unmarked,opener_conflict,contract_violation,reused,calls,plan_reads,sessions,started_with_block,deliveries,placed,identity_conflicts,duplicate_skips,scheme_conflicts,mixed_sessions FROM (SELECT q.project_id,q.session_id,q.k AS key,CAST((x.created_at - ((x.created_at % 86400000 + 86400000) % 86400000)) / 86400000 AS INTEGER) AS day,COALESCE((SELECT tr.agent FROM transcripts tr INDEXED BY idx_transcripts_session WHERE tr.project_id=x.project_id AND tr.session_id=x.session_id AND tr.role='primary' ORDER BY tr.first_received_at,tr.transcript_id LIMIT 1),'unrecorded') AS harness,
    1 AS prompts,(EXISTS (SELECT 1 FROM spore_injections r WHERE r.project_id=x.project_id AND r.session_id=x.session_id AND r.delivered_prompt_id=x.prompt_id AND r.delivered_at IS NOT NULL) OR EXISTS (SELECT 1 FROM session_injections r WHERE r.project_id=x.project_id AND r.session_id=x.session_id AND r.kind='plan-nudge' AND r.delivered_prompt_id=x.prompt_id AND r.delivered_at IS NOT NULL)) AS served,EXISTS (SELECT 1 FROM spore_injections r WHERE r.project_id=x.project_id AND r.session_id=x.session_id AND r.delivered_prompt_id=x.prompt_id AND r.delivered_at IS NOT NULL AND r.spore_ids<>'[]') AS with_spores,x.claim IS NOT NULL AS claimed,(x.claim IS NOT NULL AND x.prompt_kind='unrecognized') AS unrecognized,(x.claim IS NOT NULL AND x.prompt_kind='unmarked') AS unmarked,(x.claim IS NOT NULL AND x.prompt_kind='opener_conflict') AS opener_conflict,(x.claim IS NOT NULL AND x.prompt_kind='contract_violation') AS contract_violation,COALESCE(x.claim='reused',0) AS reused,0 AS calls,0 AS plan_reads,0 AS sessions,0 AS started_with_block,0 AS deliveries,0 AS placed,0 AS identity_conflicts,0 AS duplicate_skips,0 AS scheme_conflicts,0 AS mixed_sessions FROM (SELECT NEW.project_id AS project_id,NEW.session_id AS session_id,NEW.delivered_prompt_id AS k) q JOIN session_prompts x ON x.project_id=q.project_id AND x.session_id=q.session_id AND x.prompt_id=q.k WHERE x.generation=(SELECT doc.generation FROM session_documents doc WHERE doc.project_id=q.project_id AND doc.session_id=q.session_id AND doc.state='live')) WHERE true
      ON CONFLICT(project_id,session_id,grain,key) DO UPDATE SET (day,harness,prompts,served,with_spores,claimed,unrecognized,unmarked,opener_conflict,contract_violation,reused,calls,plan_reads,sessions,started_with_block,deliveries,placed,identity_conflicts,duplicate_skips,scheme_conflicts,mixed_sessions)=(excluded.day,excluded.harness,excluded.prompts,excluded.served,excluded.with_spores,excluded.claimed,excluded.unrecognized,excluded.unmarked,excluded.opener_conflict,excluded.contract_violation,excluded.reused,excluded.calls,excluded.plan_reads,excluded.sessions,excluded.started_with_block,excluded.deliveries,excluded.placed,excluded.identity_conflicts,excluded.duplicate_skips,excluded.scheme_conflicts,excluded.mixed_sessions)
      WHERE (kpi_fact.day,kpi_fact.harness,kpi_fact.prompts,kpi_fact.served,kpi_fact.with_spores,kpi_fact.claimed,kpi_fact.unrecognized,kpi_fact.unmarked,kpi_fact.opener_conflict,kpi_fact.contract_violation,kpi_fact.reused,kpi_fact.calls,kpi_fact.plan_reads,kpi_fact.sessions,kpi_fact.started_with_block,kpi_fact.deliveries,kpi_fact.placed,kpi_fact.identity_conflicts,kpi_fact.duplicate_skips,kpi_fact.scheme_conflicts,kpi_fact.mixed_sessions) IS NOT (excluded.day,excluded.harness,excluded.prompts,excluded.served,excluded.with_spores,excluded.claimed,excluded.unrecognized,excluded.unmarked,excluded.opener_conflict,excluded.contract_violation,excluded.reused,excluded.calls,excluded.plan_reads,excluded.sessions,excluded.started_with_block,excluded.deliveries,excluded.placed,excluded.identity_conflicts,excluded.duplicate_skips,excluded.scheme_conflicts,excluded.mixed_sessions);
DELETE FROM kpi_lineage WHERE lineage_root IN (SELECT c.lineage_root FROM sessions s JOIN member_credentials c ON c.id=s.created_by_token_id WHERE s.project_id=OLD.project_id AND s.session_id=OLD.session_id AND OLD.created_at<NEW.created_at AND OLD.created_at <= (SELECT first_served_at FROM kpi_lineage WHERE lineage_root=c.lineage_root)) AND NOT EXISTS (SELECT 1 FROM member_credentials c INDEXED BY idx_member_credentials_lineage JOIN sessions s INDEXED BY idx_sessions_credential ON s.created_by_token_id=c.id WHERE c.lineage_root=kpi_lineage.lineage_root);
INSERT INTO kpi_lineage(lineage_root,started_at,first_served_at) SELECT c.lineage_root,MIN(c.lineage_started_at),MIN((SELECT MIN(created_at) FROM (
  SELECT MIN(r.created_at) AS created_at FROM spore_injections r WHERE r.project_id=sess.project_id AND r.session_id=sess.session_id
  UNION ALL SELECT MIN(r.created_at) FROM session_injections r WHERE r.project_id=sess.project_id AND r.session_id=sess.session_id))) FROM (SELECT c.lineage_root FROM sessions s JOIN member_credentials c ON c.id=s.created_by_token_id WHERE s.project_id=OLD.project_id AND s.session_id=OLD.session_id AND OLD.created_at<NEW.created_at AND OLD.created_at <= (SELECT first_served_at FROM kpi_lineage WHERE lineage_root=c.lineage_root)) roots JOIN member_credentials c INDEXED BY idx_member_credentials_lineage ON c.lineage_root=roots.lineage_root
    JOIN sessions sess INDEXED BY idx_sessions_credential ON sess.created_by_token_id=c.id WHERE true GROUP BY c.lineage_root
    ON CONFLICT(lineage_root) DO UPDATE SET (started_at,first_served_at)=(excluded.started_at,excluded.first_served_at)
    WHERE (kpi_lineage.started_at,kpi_lineage.first_served_at) IS NOT (excluded.started_at,excluded.first_served_at);
INSERT INTO kpi_lineage(lineage_root,started_at,first_served_at) SELECT c.lineage_root,c.lineage_started_at,NEW.created_at FROM member_credentials c
   JOIN sessions s ON s.created_by_token_id=c.id WHERE s.project_id=NEW.project_id AND s.session_id=NEW.session_id
    ON CONFLICT(lineage_root) DO UPDATE SET (started_at,first_served_at)=(MIN(kpi_lineage.started_at,excluded.started_at),COALESCE(MIN(kpi_lineage.first_served_at,excluded.first_served_at),kpi_lineage.first_served_at,excluded.first_served_at))
    WHERE (kpi_lineage.started_at,kpi_lineage.first_served_at) IS NOT (MIN(kpi_lineage.started_at,excluded.started_at),COALESCE(MIN(kpi_lineage.first_served_at,excluded.first_served_at),kpi_lineage.first_served_at,excluded.first_served_at));
END;

CREATE TRIGGER IF NOT EXISTS context_placement_receipt_insert AFTER INSERT ON spore_injections BEGIN DELETE FROM context_placements WHERE kind='receipt' AND (project_id,session_id,record_id) IN (SELECT project_id,session_id,id FROM (SELECT NEW.project_id AS project_id,NEW.session_id AS session_id,NEW.id AS id))
      AND NOT EXISTS (SELECT 1 FROM spore_injections r WHERE r.project_id=context_placements.project_id AND r.session_id=context_placements.session_id AND r.id=context_placements.record_id AND NOT EXISTS (SELECT 1 FROM session_tombstones t WHERE t.project_id=r.project_id AND t.session_id=r.session_id)); INSERT INTO context_placements(project_id,session_id,kind,record_id,created_at,prompt_hint,fallback_prompt,state)
      SELECT r.project_id,r.session_id,'receipt',r.id,r.created_at,r.delivered_prompt_id,NULL,CASE WHEN r.delivered_at IS NULL THEN 'selected' WHEN r.delivered_prompt_id IS NULL THEN 'unnamed'
  WHEN EXISTS (SELECT 1 FROM session_prompts p WHERE p.project_id=r.project_id AND p.session_id=r.session_id
  AND p.generation=(SELECT d.generation FROM session_documents d WHERE d.project_id=r.project_id AND d.session_id=r.session_id AND d.state='live') AND p.prompt_id=r.delivered_prompt_id) THEN 'delivered' ELSE 'unavailable' END
      FROM (SELECT NEW.project_id AS project_id,NEW.session_id AS session_id,NEW.id AS id) key JOIN spore_injections r ON r.project_id=key.project_id AND r.session_id=key.session_id AND r.id=key.id WHERE NOT EXISTS (SELECT 1 FROM session_tombstones t WHERE t.project_id=r.project_id AND t.session_id=r.session_id) ON CONFLICT(project_id,session_id,kind,record_id) DO UPDATE SET created_at=excluded.created_at,prompt_hint=excluded.prompt_hint,fallback_prompt=excluded.fallback_prompt,state=excluded.state
  WHERE context_placements.state IS NOT excluded.state OR context_placements.prompt_hint IS NOT excluded.prompt_hint OR context_placements.created_at IS NOT excluded.created_at OR context_placements.fallback_prompt IS NOT excluded.fallback_prompt; DELETE FROM context_placements WHERE kind='answer' AND (project_id,session_id,record_id) IN (SELECT project_id,session_id,id FROM (SELECT project_id,session_id,id FROM prompt_context_answers WHERE project_id=NEW.project_id AND session_id=NEW.session_id AND receipt_id=NEW.id))
      AND NOT EXISTS (SELECT 1 FROM prompt_context_answers a WHERE a.project_id=context_placements.project_id AND a.session_id=context_placements.session_id AND a.id=context_placements.record_id AND a.outcome='served' AND NOT EXISTS (SELECT 1 FROM spore_injections receipt WHERE receipt.project_id=a.project_id AND receipt.session_id=a.session_id AND receipt.id=a.receipt_id) AND NOT EXISTS (SELECT 1 FROM session_tombstones t WHERE t.project_id=a.project_id AND t.session_id=a.session_id)); INSERT INTO context_placements(project_id,session_id,kind,record_id,created_at,prompt_hint,fallback_prompt,state)
      SELECT a.project_id,a.session_id,'answer',a.id,a.created_at,a.delivered_prompt_id,a.prompt_id,CASE WHEN a.delivered_at IS NULL THEN 'selected'
  WHEN EXISTS (SELECT 1 FROM session_prompts p WHERE p.project_id=a.project_id AND p.session_id=a.session_id
  AND p.generation=(SELECT d.generation FROM session_documents d WHERE d.project_id=a.project_id AND d.session_id=a.session_id AND d.state='live') AND p.prompt_id=a.delivered_prompt_id) OR EXISTS (SELECT 1 FROM session_prompts p WHERE p.project_id=a.project_id AND p.session_id=a.session_id
  AND p.generation=(SELECT d.generation FROM session_documents d WHERE d.project_id=a.project_id AND d.session_id=a.session_id AND d.state='live') AND p.prompt_id=a.prompt_id) THEN 'delivered'
  WHEN a.delivered_prompt_id IS NULL THEN 'unnamed' ELSE 'unavailable' END
      FROM (SELECT project_id,session_id,id FROM prompt_context_answers WHERE project_id=NEW.project_id AND session_id=NEW.session_id AND receipt_id=NEW.id) key JOIN prompt_context_answers a ON a.project_id=key.project_id AND a.session_id=key.session_id AND a.id=key.id WHERE a.outcome='served' AND NOT EXISTS (SELECT 1 FROM spore_injections receipt WHERE receipt.project_id=a.project_id AND receipt.session_id=a.session_id AND receipt.id=a.receipt_id) AND NOT EXISTS (SELECT 1 FROM session_tombstones t WHERE t.project_id=a.project_id AND t.session_id=a.session_id) ON CONFLICT(project_id,session_id,kind,record_id) DO UPDATE SET created_at=excluded.created_at,prompt_hint=excluded.prompt_hint,fallback_prompt=excluded.fallback_prompt,state=excluded.state
  WHERE context_placements.state IS NOT excluded.state OR context_placements.prompt_hint IS NOT excluded.prompt_hint OR context_placements.created_at IS NOT excluded.created_at OR context_placements.fallback_prompt IS NOT excluded.fallback_prompt; END;

